-- Consultar la tabla tal como estaba ayer a las 3:00 PM
SELECT * FROM clientes TIMESTAMP AS OF '2026-03-27 15:00:00';

-- Consultar una versión numérica específica
SELECT * FROM clientes VERSION AS OF 42;

-- Restaurar la tabla a un estado previo instantáneamente
RESTORE TABLE clientes TO VERSION AS OF 41;
